function recreateWalls(){
	for (var l = 0;l<=50; l++){
	 var newArray =  new Array(TILES_Y);
	
	 for (var y = 0; y < TILES_Y; y++) {
		newArray[y] = new Array(TILES_X); 
        for (var x = 0; x < TILES_X; x++) {
			if(walls[l][y * 32 + x]-1 == 1)
			 newArray[y][x] = 0;
            else 
            newArray[y][x] = 1;
				
		}
	 }
	 walls[l] = newArray;
	}
}
